function rangeSumBST(root, low, high) {
  let sum = 0;
  const stack = [root];
  while (stack.length > 0) {
    const node = stack.pop();
    if (node === null) continue;
    if (node.val >= low && node.val <= high) sum += node.val;
    if (node.val > low) stack.push(node.left);      // the left side may still hold values >= low
    if (node.val < high) stack.push(node.right);    // the right side may still hold values <= high
  }
  return sum;
}

def range_sum_bst(root, low, high):
    total = 0
    stack = [root]
    while stack:
        node = stack.pop()
        if node is None:
            continue
        if low <= node.val <= high:
            total += node.val
        if node.val > low:
            stack.append(node.left)       # the left side may still hold values >= low
        if node.val < high:
            stack.append(node.right)      # the right side may still hold values <= high
    return total

int rangeSumBST(TreeNode root, int low, int high) {
    int sum = 0;
    Deque<TreeNode> stack = new ArrayDeque<>();
    if (root != null) stack.push(root);
    while (!stack.isEmpty()) {
        TreeNode node = stack.pop();
        if (node.val >= low && node.val <= high) sum += node.val;
        if (node.val > low && node.left != null) stack.push(node.left);      // may still hold values >= low
        if (node.val < high && node.right != null) stack.push(node.right);   // may still hold values <= high
    }
    return sum;
}

int rangeSumBST(TreeNode* root, int low, int high) {
    int sum = 0;
    vector<TreeNode*> stack = {root};
    while (!stack.empty()) {
        TreeNode* node = stack.back();
        stack.pop_back();
        if (node == nullptr) continue;
        if (node->val >= low && node->val <= high) sum += node->val;
        if (node->val > low) stack.push_back(node->left);      // the left side may still hold values >= low
        if (node->val < high) stack.push_back(node->right);    // the right side may still hold values <= high
    }
    return sum;
}
